{
  "name": "apex-site",
  "description": "Marketing site",
  "type": "static",
  "profile": "apex-dev",
  "regions": ["us-west-2"],
  "lambda": {
    "accelerate": false,
    "warm": true,
    "warm_rate": "15m",
    "warm_count": 15,
    "memory": 512
  },
  "stages": {
    "production": {
      "domain": "gh-polls.com"
    },
    "staging": {
      "domain": "stage.gh-polls.com"
    },
    "development": {
      "domain": "dev.gh-polls.com"
    }
  },
  "hooks": {
    "build": "npm run build",
    "clean": "npm run clean",
    "prebuild": "npm run prebuild",
    "postbuild": "npm run postbuild",
    "predeploy": "npm run predeploy",
    "postdeploy": "npm run postdeploy"
  },
  "static": {
    "dir": "./dist",
    "prefix": "/static/"
  },
  "proxy": {
    "command": "node app.js",
    "timeout": 15,
    "listen_timeout": 15,
    "shutdown_timeout": 15,
    "backoff": {
      "min": 500,
      "max": 1500,
      "factor": 1.5,
      "attempts": 5,
      "jitter": false
    }
  },
  "dns": {},
  "environment": {},
  "headers": {},
  "error_pages": {
    "disable": false,
    "dir": "./dist",
    "variables": {
      "support_email": "support@apex.sh",
      "color": "#228ae6"
    }
  },
  "cors": {
    "enable": true,
    "allowed_origins": ["https://*.myapp.com"],
    "allowed_methods": ["GET", "HEAD"],
    "allowed_headers": ["Content-Type"],
    "exposed_headers": ["Content-Type"],
    "max_age": 0,
    "allowed_credentials": true
  },
  "inject": {},
  "redirects": {},
  "actions": [
    {
      "name": "slack",
      "type": "email",
      "emails": ["tj@apex.sh"]
    }
  ],
  "alerts": [
    {
      "metric": "http.count",
      "statistic": "avg",
      "threshold": 0,
      "action": "email.backend",
      "period": "1m",
      "evaluation_periods": 1,
      "operator": ">",
      "namespace": "AWS/ApiGateway",
      "description": "Huge traffic spike",
      "disable": false
    }
  ]
}

